mapper.select:
SELECT sif.* FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id WHERE sdi.dataset_id IN
#{datasetId}
ORDER BY sdi.dataset_id, sif.item_id, sif.type

SELECT COALESCE(NULLIF(sif.scene_type, ''), '未分类') AS scene_type, COUNT(*) AS count FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY COALESCE(NULLIF(sif.scene_type, ''), '未分类')

SELECT COALESCE(NULLIF(sif.haze_level, ''), '未标注') AS haze_level, COUNT(*) AS count FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY COALESCE(NULLIF(sif.haze_level, ''), '未标注')

SELECT sf.type AS file_type, COUNT(*) AS count FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id JOIN sys_file sf ON sif.file_id = sf.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY sf.type

SELECT sdi.dataset_id AS dataset_id, COUNT(*) AS cnt FROM sys_dataset_item sdi WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY sdi.dataset_id

SELECT sdi.dataset_id AS dataset_id, COUNT(sif.id) AS image_count, COALESCE(SUM(sf.size), 0) AS total_size, SUM(CASE WHEN sif.haze_level IS NOT NULL AND sif.haze_level != '' THEN 1 ELSE 0 END) AS annotated_count, SUM(CASE WHEN sif.haze_level IS NULL OR sif.haze_level = '' THEN 1 ELSE 0 END) AS unannotated_count FROM sys_dataset_item sdi LEFT JOIN sys_item_file sif ON sif.item_id = sdi.id LEFT JOIN sys_file sf ON sif.file_id = sf.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY sdi.dataset_id

SELECT sdi.dataset_id AS dataset_id, COALESCE(NULLIF(sif.scene_type, ''), '未分类') AS scene_type, COUNT(*) AS cnt FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY sdi.dataset_id, COALESCE(NULLIF(sif.scene_type, ''), '未分类')

SELECT sdi.dataset_id AS dataset_id, COALESCE(NULLIF(sif.haze_level, ''), '未标注') AS haze_level, COUNT(*) AS cnt FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY sdi.dataset_id, COALESCE(NULLIF(sif.haze_level, ''), '未标注')

SELECT sdi.dataset_id AS dataset_id, COALESCE(sf.type, '未知') AS file_type, COUNT(*) AS cnt FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id JOIN sys_file sf ON sif.file_id = sf.id WHERE sdi.dataset_id IN
#{datasetId}
GROUP BY sdi.dataset_id, COALESCE(sf.type, '未知')
